package identity

import (
	"context"
	"database/sql"
	"errors"
	"strings"
	"testing"
)

// TestIdentityGroupMembership covers the group CRUD + member-axes joint
// (task 3.2): create/get round-trip with trimmed names, duplicate-name
// refusal, rename (members and doc stay put), delete with the membership
// cascade, member-user add/remove with the decided idempotent semantics
// (re-add and remove-of-non-member are both no-ops), member-collection
// add/remove with positions (re-add re-positions), and the schema-versioned
// doc document round-trip.
func TestIdentityGroupMembership(t *testing.T) {
	ctx := context.Background()

	t.Run("create_get_roundtrip", func(t *testing.T) {
		s := openIdentityService(t)
		g, err := s.CreateGroup(ctx, "  Family  ")
		if err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if g.Name != "Family" {
			t.Fatalf("CreateGroup name = %q, want trimmed %q", g.Name, "Family")
		}
		if g.ID == 0 {
			t.Fatalf("CreateGroup id = 0, want the minted AUTOINCREMENT id")
		}
		// Fresh groups land with the column defaults: empty doc document at
		// schema version 1.
		if g.Doc != "{}" || g.SchemaVersion != 1 {
			t.Fatalf("CreateGroup doc = %q v%d, want the {} v1 defaults", g.Doc, g.SchemaVersion)
		}
		if g.CreatedAt.IsZero() || g.UpdatedAt.IsZero() {
			t.Fatalf("CreateGroup stamps = %v/%v, want both stamped", g.CreatedAt, g.UpdatedAt)
		}
		got, err := s.GetGroup(ctx, "Family")
		if err != nil {
			t.Fatalf("GetGroup: %v", err)
		}
		if got.ID != g.ID || got.Name != "Family" || got.Doc != "{}" || got.SchemaVersion != 1 {
			t.Fatalf("GetGroup = %+v, want the created row", got)
		}
	})

	t.Run("duplicate_name_refused", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.CreateGroup(ctx, "Family"); err != nil {
			t.Fatalf("CreateGroup #1: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "Family"); err == nil {
			t.Fatalf("CreateGroup duplicate = nil error, want the UNIQUE-constraint refusal")
		}
	})

	t.Run("empty_name_refused", func(t *testing.T) {
		s := openIdentityService(t)
		for _, name := range []string{"", "   "} {
			if _, err := s.CreateGroup(ctx, name); err == nil {
				t.Fatalf("CreateGroup(%q) = nil error, want refusal", name)
			}
		}
	})

	t.Run("rename_keeps_id_members_doc", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("Create user: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "old"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if err := s.AddUser(ctx, "old", "alia"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}
		doc := `{"mutes":{"com.example.plex":true}}`
		if err := s.SetGroupDoc(ctx, "old", doc, 2); err != nil {
			t.Fatalf("SetGroupDoc: %v", err)
		}
		if err := s.RenameGroup(ctx, "old", "new"); err != nil {
			t.Fatalf("RenameGroup: %v", err)
		}
		got, err := s.GetGroup(ctx, "new")
		if err != nil {
			t.Fatalf("GetGroup(new): %v", err)
		}
		if got.Doc != doc || got.SchemaVersion != 2 {
			t.Fatalf("renamed group doc = %q v%d, want %q v2 (doc stays put)", got.Doc, got.SchemaVersion, doc)
		}
		// The membership survives the rename (it keys by id, not name).
		if _, err := s.GetGroup(ctx, "old"); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("GetGroup(old) = %v, want the unknown-group error", err)
		}
		// Renaming a group that doesn't exist is the unknown-group error.
		if err := s.RenameGroup(ctx, "ghost", "any"); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("RenameGroup(ghost) = %v, want the unknown-group error", err)
		}
		// Renaming onto a taken name violates the UNIQUE constraint.
		if _, err := s.CreateGroup(ctx, "taken"); err != nil {
			t.Fatalf("CreateGroup taken: %v", err)
		}
		if err := s.RenameGroup(ctx, "new", "taken"); err == nil {
			t.Fatalf("RenameGroup onto taken name = nil error, want the UNIQUE-constraint refusal")
		}
	})

	t.Run("delete_cascades_members", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("Create user: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "doomed"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if err := s.AddUser(ctx, "doomed", "alia"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}
		if err := s.AddCollection(ctx, "doomed", 101, 1); err != nil {
			t.Fatalf("AddCollection: %v", err)
		}
		if err := s.DeleteGroup(ctx, "doomed"); err != nil {
			t.Fatalf("DeleteGroup: %v", err)
		}
		if _, err := s.GetGroup(ctx, "doomed"); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("GetGroup(deleted) = %v, want the unknown-group error", err)
		}
		if err := s.DeleteGroup(ctx, "doomed"); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("DeleteGroup(again) = %v, want the unknown-group error", err)
		}
		// The cascade is observable: a fresh group under the SAME name has no
		// leftover member rows — alia's membership and library 101 died with
		// the old row set.
		fresh, err := s.CreateGroup(ctx, "doomed")
		if err != nil {
			t.Fatalf("CreateGroup(fresh same name): %v", err)
		}
		order, err := s.CollectionOrder(ctx, fresh.ID)
		if err != nil {
			t.Fatalf("CollectionOrder(fresh group id): %v", err)
		}
		if len(order) != 0 {
			t.Fatalf("fresh group order = %+v, want empty (cascade removed old member rows)", order)
		}
	})

	t.Run("member_user_add_remove_idempotent", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.Create(ctx, "  Alia  ", "pw"); err != nil {
			t.Fatalf("Create user: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "crew"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		// Normalized username resolves; unknown user/group refuse.
		if err := s.AddUser(ctx, "crew", "ALIA"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}
		if err := s.AddUser(ctx, "ghost", "alia"); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("AddUser(unknown group) = %v, want the unknown-group error", err)
		}
		if err := s.AddUser(ctx, "crew", "nobody"); err == nil || !strings.Contains(err.Error(), "unknown user") {
			t.Fatalf("AddUser(unknown user) = %v, want the unknown-user error", err)
		}
		// Idempotent re-add (the DECIDED semantics, task 3.2): the second add
		// of a present member is a no-op, nil error.
		if err := s.AddUser(ctx, "crew", "alia"); err != nil {
			t.Fatalf("AddUser(re-add present member) = %v, want idempotent nil", err)
		}
		// Remove, then remove again — remove-of-non-member is a no-op too.
		if err := s.RemoveUser(ctx, "crew", "alia"); err != nil {
			t.Fatalf("RemoveUser: %v", err)
		}
		if err := s.RemoveUser(ctx, "crew", "alia"); err != nil {
			t.Fatalf("RemoveUser(non-member) = %v, want idempotent nil", err)
		}
		if err := s.RemoveUser(ctx, "ghost", "alia"); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("RemoveUser(unknown group) = %v, want the unknown-group error", err)
		}
		// Re-add after remove lands again (a full leave/rejoin cycle works).
		if err := s.AddUser(ctx, "crew", "alia"); err != nil {
			t.Fatalf("AddUser(rejoin): %v", err)
		}
	})

	t.Run("member_collection_positions", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.CreateGroup(ctx, "shelf"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		if err := s.AddCollection(ctx, "shelf", 101, 5); err != nil {
			t.Fatalf("AddCollection: %v", err)
		}
		// Library ids are NOT validated against the libraries table (the
		// operator-intent precedent): an arbitrary id lands fine.
		if err := s.AddCollection(ctx, "shelf", 99999, 7); err != nil {
			t.Fatalf("AddCollection(unvalidated id): %v", err)
		}
		if err := s.AddCollection(ctx, "ghost", 101, 1); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("AddCollection(unknown group) = %v, want the unknown-group error", err)
		}
		// Re-adding a carried library REPLACES its position (the re-position
		// action), never duplicating the row.
		if err := s.AddCollection(ctx, "shelf", 101, 2); err != nil {
			t.Fatalf("AddCollection(re-position): %v", err)
		}
		// Positions resolve through a MEMBER's eyes: alia joins and reads the
		// order (CollectionOrder takes the user id).
		if _, err := s.Create(ctx, "alia", "pw"); err != nil {
			t.Fatalf("Create user: %v", err)
		}
		if err := s.AddUser(ctx, "shelf", "alia"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}
		alia, err := s.Get(ctx, "alia")
		if err != nil {
			t.Fatalf("Get user: %v", err)
		}
		order, err := s.CollectionOrder(ctx, alia.ID)
		if err != nil {
			t.Fatalf("CollectionOrder: %v", err)
		}
		if len(order) != 2 || order[0].LibraryID != 101 || order[0].Position != 2 ||
			order[1].LibraryID != 99999 || order[1].Position != 7 {
			t.Fatalf("order = %+v, want 101@2 then 99999@7 (position replaced, not duplicated)", order)
		}
		// Remove is idempotent; unknown groups refuse.
		if err := s.RemoveCollection(ctx, "shelf", 101); err != nil {
			t.Fatalf("RemoveCollection: %v", err)
		}
		if err := s.RemoveCollection(ctx, "shelf", 101); err != nil {
			t.Fatalf("RemoveCollection(non-member) = %v, want idempotent nil", err)
		}
		if err := s.RemoveCollection(ctx, "ghost", 101); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("RemoveCollection(unknown group) = %v, want the unknown-group error", err)
		}
	})

	t.Run("doc_roundtrip_schema_versioned", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.CreateGroup(ctx, "muted"); err != nil {
			t.Fatalf("CreateGroup: %v", err)
		}
		// The per-source mute vocabulary (D8): shaped like the
		// metadata_source_prefs gates — plugin id → true (muted); absent
		// means not muted. Identity stores the document verbatim.
		doc := `{"mutes":{"com.example.tmdb":true,"com.example.tvdb":true}}`
		if err := s.SetGroupDoc(ctx, "muted", doc, 1); err != nil {
			t.Fatalf("SetGroupDoc: %v", err)
		}
		got, err := s.GetGroup(ctx, "muted")
		if err != nil {
			t.Fatalf("GetGroup: %v", err)
		}
		if got.Doc != doc || got.SchemaVersion != 1 {
			t.Fatalf("doc = %q v%d, want verbatim %q v1", got.Doc, got.SchemaVersion, doc)
		}
		// The write replaces WHOLE — a second write over a new version
		// carries only its own content (operator content preserved, nothing
		// merged from the stale read).
		next := `{"mutes":{"com.example.tmdb":true}}`
		if err := s.SetGroupDoc(ctx, "muted", next, 2); err != nil {
			t.Fatalf("SetGroupDoc v2: %v", err)
		}
		if got, _ = s.GetGroup(ctx, "muted"); got.Doc != next || got.SchemaVersion != 2 {
			t.Fatalf("doc = %q v%d, want whole-replace %q v2", got.Doc, got.SchemaVersion, next)
		}
		if err := s.SetGroupDoc(ctx, "ghost", next, 2); err == nil || !strings.Contains(err.Error(), "unknown group") {
			t.Fatalf("SetGroupDoc(unknown group) = %v, want the unknown-group error", err)
		}
	})

	t.Run("unknown_group_is_no_rows", func(t *testing.T) {
		s := openIdentityService(t)
		if _, err := s.GetGroup(ctx, "ghost"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetGroup(ghost) = %v, want the wrapped unknown-group (sql.ErrNoRows) error", err)
		}
	})
}

// TestIdentityCollectionOrder covers the RESOLVED display-order joint (task
// 3.2): two groups sharing a library resolve min-position, ties go to the
// lower group id, a single-group library resolves to that group's position,
// and a user's order only counts groups they belong to. Group ids track
// creation order (AUTOINCREMENT): "alpha" < "beta".
func TestIdentityCollectionOrder(t *testing.T) {
	ctx := context.Background()

	s := openIdentityService(t)
	alia, err := s.Create(ctx, "alia", "pw")
	if err != nil {
		t.Fatalf("Create user: %v", err)
	}
	sole, err := s.Create(ctx, "sole", "pw")
	if err != nil {
		t.Fatalf("Create sole user: %v", err)
	}
	alpha, err := s.CreateGroup(ctx, "alpha")
	if err != nil {
		t.Fatalf("CreateGroup alpha: %v", err)
	}
	beta, err := s.CreateGroup(ctx, "beta")
	if err != nil {
		t.Fatalf("CreateGroup beta: %v", err)
	}
	if alpha.ID >= beta.ID {
		t.Fatalf("group ids = %d/%d, want alpha < beta (AUTOINCREMENT order)", alpha.ID, beta.ID)
	}

	// Overlap: both groups carry library 101 at different positions; the
	// min-position group wins. Library 102 sits at the SAME position in
	// both — the lower group id (alpha) wins. Library 103 rides in only
	// beta — its position resolves untouched.
	for _, m := range []struct {
		group             string
		library, position int64
	}{
		{"alpha", 101, 8},
		{"beta", 101, 3},  // min position wins for 101
		{"alpha", 102, 4}, // tie with beta@4 — alpha's lower id wins
		{"beta", 102, 4},
		{"beta", 103, 6}, // single-group library
	} {
		if err := s.AddCollection(ctx, m.group, m.library, m.position); err != nil {
			t.Fatalf("AddCollection(%s,%d@%d): %v", m.group, m.library, m.position, err)
		}
	}
	// alia belongs to BOTH groups; sole belongs to alpha only.
	if err := s.AddUser(ctx, "alpha", "alia"); err != nil {
		t.Fatalf("AddUser alpha: %v", err)
	}
	if err := s.AddUser(ctx, "beta", "alia"); err != nil {
		t.Fatalf("AddUser beta: %v", err)
	}
	if err := s.AddUser(ctx, "alpha", "sole"); err != nil {
		t.Fatalf("AddUser alpha(sole): %v", err)
	}

	t.Run("min_position_wins_on_overlap", func(t *testing.T) {
		order, err := s.CollectionOrder(ctx, alia.ID)
		if err != nil {
			t.Fatalf("CollectionOrder(alia): %v", err)
		}
		// Ordered by (Position, LibraryID): 101@3 (beta), 102@4 (alpha),
		// 103@6 (beta).
		want := []CollectionOrder{
			{LibraryID: 101, Position: 3, GroupID: beta.ID},
			{LibraryID: 102, Position: 4, GroupID: alpha.ID},
			{LibraryID: 103, Position: 6, GroupID: beta.ID},
		}
		if len(order) != len(want) {
			t.Fatalf("order = %+v, want %d entries", order, len(want))
		}
		for i, w := range want {
			if order[i] != w {
				t.Fatalf("order[%d] = %+v, want %+v", i, order[i], w)
			}
		}
	})

	t.Run("group_id_tie_break", func(t *testing.T) {
		order, err := s.CollectionOrder(ctx, alia.ID)
		if err != nil {
			t.Fatalf("CollectionOrder(alia): %v", err)
		}
		for _, co := range order {
			if co.LibraryID == 102 && co.GroupID != alpha.ID {
				t.Fatalf("library 102 winner = group %d, want alpha (%d, the lower id on the @4 tie)",
					co.GroupID, alpha.ID)
			}
		}
	})

	t.Run("single_group_library_resolves_its_position", func(t *testing.T) {
		order, err := s.CollectionOrder(ctx, alia.ID)
		if err != nil {
			t.Fatalf("CollectionOrder(alia): %v", err)
		}
		for _, co := range order {
			if co.LibraryID == 103 && (co.Position != 6 || co.GroupID != beta.ID) {
				t.Fatalf("library 103 = %+v, want beta@6 (only carrier)", co)
			}
		}
	})

	t.Run("membership_scopes_resolution", func(t *testing.T) {
		// sole is in alpha only: 101 resolves to ALPHA's position (8), not
		// beta's 3, and beta-only 103 never appears — a group the user
		// doesn't belong to never votes.
		order, err := s.CollectionOrder(ctx, sole.ID)
		if err != nil {
			t.Fatalf("CollectionOrder(sole): %v", err)
		}
		want := []CollectionOrder{
			{LibraryID: 102, Position: 4, GroupID: alpha.ID},
			{LibraryID: 101, Position: 8, GroupID: alpha.ID},
		}
		if len(order) != len(want) {
			t.Fatalf("order = %+v, want %d entries (beta's 103 invisible to sole)", order, len(want))
		}
		for i, w := range want {
			if order[i] != w {
				t.Fatalf("order[%d] = %+v, want %+v", i, order[i], w)
			}
		}
	})

	t.Run("user_in_no_groups_resolves_empty", func(t *testing.T) {
		order, err := s.CollectionOrder(ctx, 424242)
		if err != nil {
			t.Fatalf("CollectionOrder(nobody): %v", err)
		}
		if order == nil || len(order) != 0 {
			t.Fatalf("order = %+v, want empty non-nil", order)
		}
	})
}

// TestIdentityUserGroups covers the profile's groups reader (task 8.1): the
// user's LIVE group rows joined through group_members, ordered by name, a
// non-member's groups excluded, and the no-group user resolving to the
// empty non-nil slice. A membership whose group row was deleted joins to
// nothing (the DeleteGroup cascade removes it anyway — the join is the
// same live-rows discipline ResolveViewer rides).
func TestIdentityUserGroups(t *testing.T) {
	s := openIdentityService(t)
	ctx := context.Background()

	if _, err := s.Create(ctx, "alia", "pw"); err != nil {
		t.Fatalf("Create alia: %v", err)
	}
	if _, err := s.Create(ctx, "noor", "pw"); err != nil {
		t.Fatalf("Create noor: %v", err)
	}
	for _, name := range []string{"Zeta", "Alpha"} {
		if _, err := s.CreateGroup(ctx, name); err != nil {
			t.Fatalf("CreateGroup %s: %v", name, err)
		}
	}
	if err := s.AddUser(ctx, "Zeta", "alia"); err != nil {
		t.Fatalf("AddUser Zeta: %v", err)
	}
	if err := s.AddUser(ctx, "Alpha", "alia"); err != nil {
		t.Fatalf("AddUser Alpha: %v", err)
	}

	uid, err := s.userID(ctx, "alia")
	if err != nil {
		t.Fatalf("userID alia: %v", err)
	}
	groups, err := s.UserGroups(ctx, uid)
	if err != nil {
		t.Fatalf("UserGroups: %v", err)
	}
	if len(groups) != 2 || groups[0].Name != "Alpha" || groups[1].Name != "Zeta" {
		t.Fatalf("groups = %+v, want [Alpha Zeta] in name order", groups)
	}
	if groups[0].ID == 0 || groups[0].ID == groups[1].ID {
		t.Fatalf("group ids not carried/distinct: %+v", groups)
	}

	// The other user's membership set is independent; the no-group user is
	// the empty non-nil slice.
	noorID, err := s.userID(ctx, "noor")
	if err != nil {
		t.Fatalf("userID noor: %v", err)
	}
	noorGroups, err := s.UserGroups(ctx, noorID)
	if err != nil {
		t.Fatalf("UserGroups noor: %v", err)
	}
	if noorGroups == nil || len(noorGroups) != 0 {
		t.Fatalf("noor groups = %+v, want empty non-nil", noorGroups)
	}

	// Removal is reflected on the next read (live rows, never a snapshot).
	if err := s.RemoveUser(ctx, "Alpha", "alia"); err != nil {
		t.Fatalf("RemoveUser: %v", err)
	}
	groups, err = s.UserGroups(ctx, uid)
	if err != nil {
		t.Fatalf("UserGroups after remove: %v", err)
	}
	if len(groups) != 1 || groups[0].Name != "Zeta" {
		t.Fatalf("groups after remove = %+v, want [Zeta] only", groups)
	}
}
